    { type: 'freddy', x: -1.05, z: 7.0, rot: .06, scale: 1.06 },
    { type: 'foxy', x: 1.15, z: 7.0, rot: -.08, scale: 1.02 }
  ];
  for (const sp of specs) {
    const a = makeAnimatronic(sp.type);
    a.group.position.set(sp.x, 0, sp.z);
    a.group.rotation.y = Math.PI + sp.rot;
    a.group.scale.setScalar(sp.scale);
    a.group.position.y = .5;
    a.group.traverse(o => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; } });
    a.eyeMat.emissiveIntensity = 1.9;
    g.add(a.group);
    this.menuChars[sp.type] = a;
  }
  // floating dust
  const geo = new THREE.BufferGeometry();
  const n = 150, arr = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) { arr[i * 3] = (Math.random() - .5) * 14; arr[i * 3 + 1] = Math.random() * 5; arr[i * 3 + 2] = Math.random() * 11; }
  geo.setAttribute('position', new THREE.BufferAttribute(arr, 3));
  g.add(new THREE.Points(geo, new THREE.PointsMaterial({ color: 0xffdcaa, size: .02, transparent: true, opacity: .28, depthWrite: false, blending: THREE.AdditiveBlending })));

  // menu footer sign
  const signM = new THREE.MeshStandardMaterial({ map: signTexture(), roughness: .8, emissive: 0x1a1208, emissiveIntensity: .4 });
  const sgn = plane(4.2, 2.1, signM, 0, .75, 4.82);
  sgn.rotation.x = -.35;
  g.add(sgn);
}

